import{_ as i,l as o,o as e,c as s,v as t,p as l,x as r,d as A,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"内存控制器与 DRAM 时序","description":"","frontmatter":{"title":"内存控制器与 DRAM 时序","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dram-timing.md","filePath":"cs/dram-timing.md","lastUpdated":1789023840000}'),p={name:"cs/dram-timing.md"};function m(h,a,E,_,D,R){const n=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="内存控制器与-dram-时序" tabindex="-1">内存控制器与 DRAM 时序 <a class="header-anchor" href="#内存控制器与-dram-时序" aria-label="Permalink to &quot;内存控制器与 DRAM 时序&quot;">​</a></h1><div class="epigraph"><p>一次 cache 缺失不是「一个 DRAM 延迟」：行要打开，列要选，预充电要等；控制器把这些命令排成日程。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach；对照 JEDEC SDRAM 时序参数 整理</footer></div><p><a href="/cs/interconnect-numa">上一课</a>让远程访问走互连，并假定本地内存仍是一个均匀的延迟数。<a href="/cs/memory-array-sram-dram">SRAM 与 DRAM 阵列</a>已说明电容与刷新。本课不重讲 NUMA 拓扑。缺口是内存控制器：把 MSHR 传来的块请求翻译成 ACT/RD/WR/PRE 命令，遵守 \\(t_{RCD}\\)、\\(t_{CAS}\\)、\\(t_{RP}\\) 一类间隔。体系结构课在此把「缺失代价」收成可调度的时间表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DRAM 按 bank、行、列组织。读指定列之前，该 bank 必须已打开正确的行（ACT，等 \\(t_{RCD}\\)），再发读（等 \\(t_{CAS}\\)）。换行要先 PRE（等 \\(t_{RP}\\)）再 ACT。同一 bank 上的请求若行冲突，延迟远大于行命中。缺口不是再加一层 cache，而是<strong>控制器选择先服务哪一个 MSHR，以增加行命中、遵守时序、并在刷新窗口插入 REF</strong>。</p><p>通道、rank、bank 并行：独立 bank 可交叉，把块填充的有效带宽拉上去。NUMA 的「本地」仍过这一套；远程只是请求先到别的控制器。</p><p><span class="marginnote">教材常把 \\(t_{CAS}\\)、\\(t_{RCD}\\)、\\(t_{RP}\\) 写成一组。绝对纳秒随产品变，本课钉结构和相对关系，不背某代 DDR 的数字。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>控制器维护每 bank 的打开行。策略：先到先服务会打进行颠簸；常见是优先同行请求、在公平性约束下调度。写缓冲与读请求冲突时，往往攒写、读优先，以免 load 等一串 store。</p>',9)),(e(),l(c,null,{default:r(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20MSHR%5B%22MSHR%20%E5%9D%97%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20MC%5B%22%E5%86%85%E5%AD%98%E6%8E%A7%E5%88%B6%E5%99%A8%22%5D%0A%20%20MC%20--%3E%20ACT%5B%22ACT%20%E6%89%93%E5%BC%80%E8%A1%8C%22%5D%0A%20%20ACT%20--%3E%20COL%5B%22RD%2FWR%20%E5%88%97%E5%91%BD%E4%BB%A4%22%5D%0A%20%20COL%20--%3E%20PRE%5B%22%E6%8D%A2%E8%A1%8C%E5%88%99%20PRE%22%5D%0A%20%20MC%20--%3E%20REF%5B%22%E5%88%B7%E6%96%B0%E7%AA%97%E5%8F%A3%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>ECC、突发长度、命令/地址与数据总线的时分，本课只承认它们影响一次填充的拍数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>cache 缺失代价 = 排队 + 命令间隔 + 数据突发。预取与写回会改变队列成分：预取可能提高行局部性，也可能挤掉需求读。包含层次决定写回落在哪一层，最终仍可能变成 DRAM 写。</p><p><a href="/cs/cpi-amdahl">阿姆达尔</a>：只加速 ALU 不管控制器队列，存储器 \\(f\\) 封顶。操作系统的页放置改变的是「哪一个控制器」，不改变 bank 时序规则。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不进入 HBM 堆叠工艺，不把具体 DDR 代数当课名。也不把控制器调度写成操作系统磁盘电梯——对象是纳秒级命令，不是毫秒级寻道。数据结构课即将开始：程序员选的布局会改变行命中与 cache 轨迹，但 ADT 先从接口讲起。</p><p>后课默认：DRAM 访问有行状态与时序；缺失代价不是常数。下一课程用抽象数据类型命名可复用的比特布局。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>控制器把缺失变成 ACT/列/PRE/刷新日程；行冲突比行命中贵。</li><li>调度与多 bank 交叉决定有效缺失延迟。</li><li>体系结构主干收到这里；下一课开始 ADT。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em> DRAM 与内存系统；JEDEC SDRAM 时序参数命名。</li></ul>',9))])}const M=i(p,[["render",m]]);export{u as __pageData,M as default};
